using System;
using System.Linq;
using NUnit.Framework;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
public sealed class NinjaSceneTests
{
 Component match;SerializedObject data;
 [OneTimeSetUp]public void Open(){EditorSceneManager.OpenScene("Assets/TruckNinjaWarrior/Scenes/TruckNinjaWarrior.unity");var type=Type.GetType("LWS.TruckNinjaWarrior.NinjaMatch, Assembly-CSharp",true);match=Resources.FindObjectsOfTypeAll(type).Cast<Component>().First(c=>c.gameObject.scene.IsValid());data=new SerializedObject(match);}
 [Test]public void EveryAuthoredBehaviourAndSharedPresentationReferenceResolves(){foreach(var root in match.gameObject.scene.GetRootGameObjects())foreach(var t in root.GetComponentsInChildren<Transform>(true))Assert.Zero(GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject),t.name);foreach(string name in new[]{"drivingViews","broadcast","atmosphere","menus","feedback"})Assert.NotNull(data.FindProperty(name).objectReferenceValue,name);Assert.NotNull(AssetDatabase.LoadAssetAtPath<Sprite>("Assets/TruckSports/Art/Logos/TruckNinjaWarrior.png"));}
 [Test]public void SixObstacleCheckpointsHavePhysicalLandingSurfaces(){var course=new SerializedObject(data.FindProperty("course").objectReferenceValue);var checkpoints=course.FindProperty("checkpoints");Assert.AreEqual(6,checkpoints.arraySize);Assert.AreEqual(6,course.FindProperty("obstacles").arraySize);Physics.SyncTransforms();for(int i=0;i<6;i++){var p=checkpoints.GetArrayElementAtIndex(i).vector3Value;Assert.True(Physics.Raycast(p+Vector3.up*10,Vector3.down,out var hit,15,1,QueryTriggerInteraction.Ignore),"checkpoint "+i);Assert.Less(Mathf.Abs(p.y-hit.point.y),1.4f);}}
 [Test]public void MovingObstaclesBellAndAthletesAreFullyBound(){var course=new SerializedObject(data.FindProperty("course").objectReferenceValue);Assert.AreEqual(course.FindProperty("movingBodies").arraySize,course.FindProperty("dynamicAtGo").arraySize);Assert.Greater(course.FindProperty("movingBodies").arraySize,10);var bell=(Rigidbody)course.FindProperty("bell").objectReferenceValue;Assert.NotNull(bell.GetComponent<Collider>());Assert.NotNull(bell.GetComponent<HingeJoint>());Assert.AreEqual(8,data.FindProperty("athletes").arraySize);}

 [Test]public void FirstStepLandingLeavesARealButReachableChargedJump(){Physics.SyncTransforms();var landing=UnityEngine.Object.FindObjectsByType<Transform>(FindObjectsInactive.Include).First(t=>t.name=="Broad safe checkpoint landing"&&Mathf.Abs(t.position.z-123)<.1f);var deck=landing.Find("Actual full-sized physical obstacle deck");Assert.AreEqual(102,deck.GetComponent<BoxCollider>().bounds.min.z,.05f);Assert.AreEqual(42,deck.GetComponent<MeshRenderer>().bounds.size.z,.05f);Assert.That(deck.GetComponent<BoxCollider>().bounds.min.z-88.5f,Is.InRange(13f,14f),"Keep a genuine gap after the final tilting step, without requiring a lucky high-speed launch.");}
 [Test]public void IntendedSupportDoesNotTriggerWallAvoidanceButKeepsPhysicalCollision(){var actor=new GameObject("Isolated navigation test actor");var support=GameObject.CreatePrimitive(PrimitiveType.Cube);try{actor.transform.position=new Vector3(5000,2000,5000);var body=actor.AddComponent<Rigidbody>();body.isKinematic=true;support.transform.position=actor.transform.position+new Vector3(0,1.1f,5);support.transform.localScale=new Vector3(4,8,1);var shape=support.GetComponent<Collider>();Physics.SyncTransforms();var type=Type.GetType("LWS.TruckFareFight.FareFightRoute, Assembly-CSharp",true);var driver=Activator.CreateInstance(type);type.GetMethod("DirectGoal").Invoke(driver,new object[]{body.position,body.position+Vector3.forward*100});var drive=type.GetMethod("Drive");drive.Invoke(driver,new object[]{body,actor.transform,2,.02f,1f,null,null});Assert.Less((float)type.GetProperty("DesiredSpeed").GetValue(driver),1,"An ordinary solid obstacle must still stop AI.");drive.Invoke(driver,new object[]{body,actor.transform,2,.02f,1f,null,shape});Assert.Greater((float)type.GetProperty("DesiredSpeed").GetValue(driver),10,"An explicitly intended ramp must retain approach momentum.");Assert.True(shape.enabled);Assert.False(shape.isTrigger);}finally{UnityEngine.Object.DestroyImmediate(actor);UnityEngine.Object.DestroyImmediate(support);}}
 [Test]public void StartingDeckDoesNotPenetrateTheFirstTiltingStep(){var course=new SerializedObject(data.FindProperty("course").objectReferenceValue);var step=(Rigidbody)course.FindProperty("movingBodies").GetArrayElementAtIndex(0).objectReferenceValue;var a=GameObject.Find("Grounded starting showcase platform").transform.Find("Actual full-sized physical obstacle deck").GetComponent<BoxCollider>();var b=step.transform.Find("Actual full-sized physical obstacle deck").GetComponent<BoxCollider>();Physics.SyncTransforms();bool overlap=Physics.ComputePenetration(a,a.transform.position,a.transform.rotation,b,b.transform.position,b.transform.rotation,out var normal,out var depth);Assert.False(overlap,"Unloaded moving step intersects solid starting deck: depth="+depth+" normal="+normal);}
 [Test]public void WeightDrivenDecksAreJointedToTheirOwnCollisionIsolatedSupports(){var course=new SerializedObject(data.FindProperty("course").objectReferenceValue);var bodies=course.FindProperty("movingBodies");int found=0;for(int i=0;i<bodies.arraySize;i++){var body=(Rigidbody)bodies.GetArrayElementAtIndex(i).objectReferenceValue;var joint=body.GetComponent<ConfigurableJoint>();if(joint==null||!body.name.Contains("step")&&!body.name.Contains("seesaw"))continue;found++;Assert.NotNull(joint.connectedBody,body.name+" needs its own hinge support rather than collisions between the deck and interlocking static support.");Assert.True(joint.connectedBody.isKinematic);Assert.False(joint.enableCollision);Assert.Greater(joint.connectedBody.GetComponentsInChildren<Collider>().Length,0);Assert.Less(Vector3.Distance(body.transform.TransformPoint(joint.anchor),joint.connectedBody.transform.TransformPoint(joint.connectedAnchor)),.01f);}Assert.AreEqual(4,found);}
 [Test]public void WeightDrivenDecksDoNotIntersectUnconnectedStaticGeometry(){Physics.SyncTransforms();var course=new SerializedObject(data.FindProperty("course").objectReferenceValue);var bodies=course.FindProperty("movingBodies");var solids=UnityEngine.Object.FindObjectsByType<Collider>(FindObjectsSortMode.None).Where(c=>c.enabled&&!c.isTrigger&&c.attachedRigidbody==null).ToArray();var contacts=new System.Collections.Generic.List<string>();for(int i=0;i<bodies.arraySize;i++){var body=(Rigidbody)bodies.GetArrayElementAtIndex(i).objectReferenceValue;if(body.GetComponent<ConfigurableJoint>()==null||!body.name.Contains("step")&&!body.name.Contains("seesaw"))continue;foreach(var shape in body.GetComponentsInChildren<Collider>())if(shape.enabled&&!shape.isTrigger)foreach(var solid in solids)if(shape.bounds.Intersects(solid.bounds)&&Physics.ComputePenetration(shape,shape.transform.position,shape.transform.rotation,solid,solid.transform.position,solid.transform.rotation,out var direction,out var depth)&&depth>.005f)contacts.Add(body.name+" intersects "+solid.name+" at "+solid.transform.position+" depth="+depth+" normal="+direction);}Assert.IsEmpty(contacts,string.Join("\n",contacts));}
 [Test]public void AIReferencesTheGenuineCollidableWarpedWall(){var course=new SerializedObject(data.FindProperty("course").objectReferenceValue);var ramp=GameObject.Find("Genuine curved warped-wall collision surface").GetComponent<MeshCollider>();Assert.AreSame(ramp,course.FindProperty("warpedWall").objectReferenceValue);Assert.True(ramp.enabled);Assert.False(ramp.isTrigger);Assert.AreSame(ramp.sharedMesh,ramp.GetComponent<MeshFilter>().sharedMesh);}
 [Test]public void WarpedWallAndVictoryLandingHaveMatchingHeightAndContinuousEdges(){var ramp=GameObject.Find("Genuine curved warped-wall collision surface").GetComponent<Collider>().bounds;var landing=GameObject.Find("Elevated full-truck victory landing").GetComponentInChildren<Collider>().bounds;Assert.AreEqual(ramp.max.z,landing.min.z,.06f);Assert.AreEqual(ramp.max.y,landing.max.y,.06f);}
}
